/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const pubofrYn = $c.util.getComponent("dma_registerReq").get("pubofrYn");
    if (($c.util.getComponent('cal_pubofrStatSubmitDd').getValue() == null ? '' : String($c.util.getComponent('cal_pubofrStatSubmitDd').getValue())) === '') {
        await $c.win.alert('신고서제출일자를 입력하여 주십시오');
        return;
    }
    if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) === '') {
        await $c.win.alert('상장(희망)일을 입력하여 주십시오');
        return;
    }
    if (pubofrYn === 'N') {
        if (!await $c.win.confirm('공모없음이 체크되어 있습니다. \n 계속 진행할 경우 입력내용이 모두 삭제 됩니다. 계속 하시겠습니까?')) {
            return;
        }
        if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) !== '') {
            if ($c.util.getComponent("dma_registerReq").get("possibleYn") !== 'Y') {
                await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                return;
            }
        }
    } else {
        $c.util.getComponent("dma_registerReq").set("pubofrYn", 'Y');
        if (($c.util.getComponent('cal_pubofrSchdlStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_pubofrSchdlStrtDd').getValue())) === '') {
            await $c.win.alert('청약예정시작일을 입력하여 주십시오');
            return;
        }
        if (($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) !== '') {
            if ($c.util.getComponent("dma_registerReq").get("possibleYn") !== 'Y') {
                await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                return;
            }
        }
        if (!(String(($c.util.getComponent('rd_nparvalstkYn'))?.getValue?.() ?? "") !== "")) {
            await $c.win.alert('무액면주식여부는 필수 입니다.');
            return;
        }
    }
    if ($c.util.getComponent("dma_registerReq").get("pubofrWrtTpCd") === '') {
        $c.util.getComponent("dma_registerReq").set("method", 'insertPubOfrSchdl');
    } else {
        if ($c.util.getComponent("dma_registerReq").get("pubofrWrtTpCd") === '1') {
            $c.util.getComponent("dma_registerReq").set("method", 'updatePubOfrSchdl');
        }
    }
    await scwin.tx_fn_register('pubOfrSchdl.do');
};

