    const nr = await scwin.tx_fn_goPage(action);
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL53100.xml", { "method": 'searchPubOfrSchdl' });
    }
};

/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (str) {
    str = str.replace(/^\s*/, '').replace(/\s*$/, '');
    return str;
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj) {
    if (scwin.calBytes(obj.value) > 4000) {
        await $c.win.alert('한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name setLength
 * @description set Length 처리
 * @param {Object} obj 컴포넌트
 * @param {*} tdName tdName
 * @param {*} maxLength maxLength
 * @returns {void}
 * @hidden N
 */
scwin.setLength = function (obj, tdName, maxLength) {
    const strLength = scwin.calBytes(obj);
    ($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setValue) ? $c.util.getComponent(tdName).setValue("  (" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setText) ? $c.util.getComponent(tdName).setText("  (" + strLength + "/" + maxLength + ")") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdName), void ("  (" + strLength + "/" + maxLength + ")")));
};

/**
 * @method
 * @name checkNumber1
 * @description check Number1 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber1 = async function (obj) {
    if (/[^0123456789.]/g.test(obj.value)) {
        await $c.win.alert("숫자가 아닙니다.\n\n0-9의 정수만 허용합니다.");
        obj.select();
        return;
    }
    if (parseFloat(obj.value) > 100) {
        await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
        obj.select();
        return;
    }
    if (obj.value.indexOf(".") > 0) {
        if (obj.value.substring(obj.value.indexOf(".") + 1).length > 6) {
            await $c.win.alert('소수 6자리까지 입력할 수 있습니다');
            obj.select();
            return;
        }
    } else {
        if (obj.value.length > 3) {
            await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
            obj.select();
            return;
        }
    }
};

/**
 * @method
 * @name sumPub
 * @description sum Pub 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.sumPub = function (ver) {
    let tVer1;
    let tVer2;
    let tVer3;
    if (ver === '0') {
        $c.util.getComponent("ipt_pubofrShrsAgg").setValue(scwin.rmComma($c.util.getComponent('ipt_oferPubofrShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_salePubofrShrs').getValue()));
    } else {
        if (ver === '1') {
            $c.util.getComponent("ipt_lwlmtPubofrSchdlTotamt").setValue(scwin.rmComma($c.util.getComponent('ipt_oferLwlmtPubofrShdlAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_saleLwlmtPubofrShdlAmt').getValue()));
        } else {
            $c.util.getComponent("ipt_uplmtPubofrSchdlTotamt").setValue(scwin.rmComma($c.util.getComponent('ipt_oferUplmtPubofrShdlAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_saleUplmtPubofrShdlAmt').getValue()));
        }
    }
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};
